77	@RestController
78	@CrossOrigin(exposedHeaders = "errors, content-type")
79	@RequestMapping("/api")
80	public class OwnerRestControllerV1 implements OwnersApi {
81	
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    private final TelephoneNormalizer telephoneNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    private final EmailNormalizer emailNormalizer;
97	
98	    private final DisposableEmailDomains disposableEmailDomains;
99	
100	    private final Sha256Hasher sha256Hasher;
101	
102	    private final Soundex soundex;
103	
104	    private final IdempotencyKeyStore idempotencyKeyStore;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper,
110	                                 TelephoneNormalizer telephoneNormalizer,
111	                                 AddressNormalizer addressNormalizer,
112	                                 EmailNormalizer emailNormalizer,
113	                                 DisposableEmailDomains disposableEmailDomains,
114	                                 Sha256Hasher sha256Hasher,
115	                                 Soundex soundex,
116	                                 IdempotencyKeyStore idempotencyKeyStore) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	        this.telephoneNormalizer = telephoneNormalizer;
122	        this.addressNormalizer = addressNormalizer;
123	        this.emailNormalizer = emailNormalizer;
124	        this.disposableEmailDomains = disposableEmailDomains;
125	        this.sha256Hasher = sha256Hasher;
126	        this.soundex = soundex;
127	        this.idempotencyKeyStore = idempotencyKeyStore;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        return withOwner(ownerId, owner ->
149	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
150	    }
151	
152	    /**
153	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
154	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
155	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
156	     */
157	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
162	        String idempotencyKey = currentIdempotencyKey();
163	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
164	            .map(this.clinicService::findOwnerById);
165	        if (existing.isPresent()) {
166	            return ownerResponse(existing.get(), HttpStatus.OK);
167	        }
168	        Owner owner = createOwner(ownerFieldsDto);
169	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
170	        return ownerResponse(owner, HttpStatus.CREATED);
171	    }
172	
173	    /**
174	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
175	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
176	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
177	     * originally created owner.
178	     *
179	     * @return the request's idempotency key, or {@code null} when none was supplied
180	     */
181	    private String currentIdempotencyKey() {
182	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
183	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
184	        }
185	        return null;
186	    }
187	
188	    /**
189	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
190	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
191	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
192	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
193	     * then respond" and the persisted owner is available to callers that need it beyond the response.
194	     *
195	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
196	     * @return the persisted owner, with its derived fields populated
197	     */
198	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
199	        normalizeAddress(ownerFieldsDto);
200	        rejectBlankOwnerFields(ownerFieldsDto);
201	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
202	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
203	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
204	        rejectCityAtCapacity(ownerFieldsDto.getCity());
205	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
206	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
207	        rejectDailyRegistrationLimit(registrationDate);
208	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
209	        ownerFieldsDto.setTelephone(normalizedTelephone);
210	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
211	        ownerFieldsDto.setEmail(normalizedEmail);
212	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
213	        owner.setRegistrationDate(registrationDate);
214	        owner.setCustomerCode(customerCode(owner));
215	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
216	        owner.setHouseholdId(householdId(owner));
217	        rejectDuplicateIdentity(owner);
218	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
219	        this.clinicService.saveOwner(owner);
220	        owner.setHouseholdSize(householdSize(owner));
221	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
222	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
223	            membershipLevel(owner), ownerMapper.membershipNumber(owner));
224	        return owner;
225	    }
226	
227	    /**
228	     * Builds the response for an owner: its derived-field DTO (see
229	     * {@link #toOwnerDtoWithDerivedFields(Owner)}) as the body and a {@code Location} header pointing at
230	     * the owner's canonical URL, returned with the given {@code status}. Assembling the response in one
231	     * place keeps "what to return for an owner" separate from the create flow that produced it, so any
232	     * path that returns an owner does so identically (differing only in the status it carries).
233	     *
234	     * @param owner the persisted owner to represent
235	     * @param status the HTTP status to return
236	     * @return the owner response with its body, {@code Location} header and status
237	     */
238	    private ResponseEntity<OwnerDto> ownerResponse(Owner owner, HttpStatus status) {
239	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
240	        HttpHeaders headers = new HttpHeaders();
241	        headers.setLocation(UriComponentsBuilder.newInstance()
242	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
243	        return new ResponseEntity<>(ownerDto, headers, status);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
249	        return withOwner(ownerId, currentOwner -> {
250	            currentOwner.setAddress(ownerFieldsDto.getAddress());
251	            currentOwner.setCity(ownerFieldsDto.getCity());
252	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
253	            currentOwner.setLastName(ownerFieldsDto.getLastName());
254	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
255	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
256	            this.clinicService.saveOwner(currentOwner);
257	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
258	        });
259	    }
260	
261	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
262	    @Transactional
263	    @Override
264	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
265	        return withOwner(ownerId, owner -> {
266	            owner.setDeleted(true);
267	            this.clinicService.saveOwner(owner);
268	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
269	        });
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
275	        return withOwner(ownerId, owner -> {
276	            HttpHeaders headers = new HttpHeaders();
277	            Pet pet = petMapper.toPet(petFieldsDto);
278	            owner.setId(ownerId);
279	            pet.setOwner(owner);
280	            pet.getType().setName(null);
281	            this.clinicService.savePet(pet);
282	            PetDto petDto = petMapper.toPetDto(pet);
283	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
284	                .buildAndExpand(pet.getId()).toUri());
285	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
286	        });
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
292	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
293	        if (currentOwner != null) {
294	            Pet currentPet = this.clinicService.findPetById(petId);
295	            if (currentPet != null) {
296	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
297	                currentPet.setName(petFieldsDto.getName());
298	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
299	                this.clinicService.savePet(currentPet);
300	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
301	            }
302	        }
303	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
304	    }
305	
306	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
307	    @Override
308	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
309	        HttpHeaders headers = new HttpHeaders();
310	        Visit visit = visitMapper.toVisit(visitFieldsDto);
311	        Pet pet = new Pet();
312	        pet.setId(petId);
313	        visit.setPet(pet);
314	        this.clinicService.saveVisit(visit);
315	        VisitDto visitDto = visitMapper.toVisitDto(visit);
316	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
317	            .buildAndExpand(visit.getId()).toUri());
318	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
319	    }
320	
321	
322	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
323	    @Override
324	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
325	        Owner owner = this.clinicService.findOwnerById(ownerId);
326	        if (owner != null) {
327	            Pet pet = owner.getPet(petId);
328	            if (pet != null) {
329	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
330	            }
331	        }
332	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
333	    }
334	
335	    /**
336	     * Loads the owner with the given id and, when it exists, produces the response through
337	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
338	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
339	     * the not-found response are written in exactly one place rather than copied into each method.
