378	    /**
379	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
380	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
381	     * routed through the controller so the create audit log and the single-owner response agree on one
382	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
383	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
384	     *
385	     * <p>Household ceiling: the reported level is capped at one above the current maximum
386	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
387	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
388	     * than the owner itself). With no existing household member no cap applies and the owner-local level
389	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
390	     * capped level), so it depends only on the members' own points and cannot recurse.
391	     *
392	     * @param owner the owner whose reported membership level is wanted
393	     * @return the owner's membership level, capped at one above its household maximum
394	     */
395	    private Integer membershipLevel(Owner owner) {
396	        int ownLevel = ownerMapper.membershipLevel(owner);
397	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
398	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
399	            .mapToInt(this::householdMemberLevel)
400	            .max();
401	        if (maxHouseholdLevel.isEmpty()) {
402	            return ownLevel;
403	        }
404	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
405	    }
