407	    /**
408	     * The owner-local membership level of a household member, used only as an input to the household
409	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
410	     * household size} is set from its household before the level is derived, so the member's household
411	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
412	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
413	     *
414	     * @param member an existing member of an owner's household
415	     * @return the member's owner-local membership level
416	     */
417	    private int householdMemberLevel(Owner member) {
418	        member.setHouseholdSize(householdSize(member));
419	        return ownerMapper.membershipLevel(member);
420	    }
