422	    /**
423	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
424	     * every later step - the required-field check, the persisted value and the response - sees the
425	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
426	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
427	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
428	     * steps that read the address.
429	     *
430	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
431	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
432	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
433	     * are preferred when present: the flat {@code address} returned is composed as the normalized
434	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
435	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
436	     * {@code address} retain its own normalized value.
437	     *
438	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
439	     */
440	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
441	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
442	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
443	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
444	        ownerFieldsDto.setAddressLine1(addressLine1);
445	        ownerFieldsDto.setAddressLine2(addressLine2);
446	        if (addressLine1 != null && !addressLine1.isBlank()) {
447	            String composed = addressLine2 != null && !addressLine2.isBlank()
448	                ? addressLine1 + " " + addressLine2
449	                : addressLine1;
450	            ownerFieldsDto.setAddress(composed);
451	        } else {
452	            ownerFieldsDto.setAddress(flatAddress);
453	        }
454	    }
