456	    /**
457	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
458	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
459	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
460	     * blank (e.g. {@code "   "}). The offending field names are reported through an
461	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
462	     * as a 400 response carrying an {@code errors} array of field names.
463	     *
464	     * @param ownerFieldsDto the submitted owner fields
465	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
466	     */
467	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
468	        List<String> blankFields = new ArrayList<>();
469	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
470	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
471	        addRequiredAddress(blankFields, ownerFieldsDto);
472	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
473	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
474	        if (!blankFields.isEmpty()) {
475	            throw new InvalidOwnerFieldsException(blankFields);
476	        }
477	    }
