485	    /**
486	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
487	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
488	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
489	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
490	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
491	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
492	     *
493	     * @param blankFields the accumulating list of blank required-field names
494	     * @param ownerFieldsDto the submitted owner fields
495	     */
496	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
497	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
498	            blankFields.add("address");
499	        }
