550	    /**
551	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
552	     * the {@code customerCode}.
553	     */
554	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
555	
556	    /**
557	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
558	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
559	     * its {@code postcode} (falling back to its {@code city}) through the shared
560	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
561	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
562	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
563	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
564	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
565	     * distinct customer codes.
566	     *
567	     * @param owner the owner being created, with its telephone already normalized
568	     * @return the formatted, de-duplicated customer code
569	     */
570	    private String customerCode(Owner owner) {
571	        String region = Region.code(owner.getPostcode(), owner.getCity());
572	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
573	        String base = region + "-" + hash8;
574	        return deduplicateCustomerCode(base);
575	    }
576	
577	    /**
578	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
579	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
580	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
581	     * held by no existing owner.
582	     *
583	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
584	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
585	     */
586	    private String deduplicateCustomerCode(String base) {
587	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
588	            .map(Owner::getCustomerCode)
589	            .filter(java.util.Objects::nonNull)
590	            .collect(java.util.stream.Collectors.toSet());
591	        if (!existing.contains(base)) {
592	            return base;
593	        }
594	        int n = 2;
595	        while (existing.contains(base + "-" + n)) {
596	            n++;
597	        }
598	        return base + "-" + n;
599	    }
