694	    /**
695	     * The fixed list of public holidays that are not business days. A registration date that lands
696	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
697	     * business day, exactly as it is rolled forward off a weekend.
698	     */
699	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
700	        LocalDate.of(2026, 1, 1),
701	        LocalDate.of(2026, 1, 26),
702	        LocalDate.of(2026, 4, 25),
703	        LocalDate.of(2026, 12, 25),
704	        LocalDate.of(2026, 12, 28));
