706	    /**
707	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
708	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
709	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
710	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
711	     * value - whether supplied in the request or defaulted to the server date - is stored as the
712	     * next business day, and every value derived from the registration date (such as the membership
713	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
714	     *
715	     * @param date the effective registration date
716	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
717	     */
718	    private LocalDate businessDay(LocalDate date) {
719	        while (isNonBusinessDay(date)) {
720	            date = date.plusDays(1);
721	        }
722	        return date;
723	    }
