725	    /**
726	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
727	     *
728	     * @param date the date to test
729	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
730	     */
731	    private boolean isNonBusinessDay(LocalDate date) {
732	        DayOfWeek dayOfWeek = date.getDayOfWeek();
733	        return dayOfWeek == DayOfWeek.SATURDAY
734	            || dayOfWeek == DayOfWeek.SUNDAY
735	            || PUBLIC_HOLIDAYS.contains(date);
736	    }
