741	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
742	     * renders as a 429 Too Many Requests response.
743	     *
744	     * @param date the registration date of the owner being created (today)
745	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
746	     */
747	    private void rejectDailyRegistrationLimit(LocalDate date) {
