817	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
818	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
819	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
820	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
821	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
822	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
823	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
824	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
825	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
826	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
827	     *
828	     * @param owner the fully-populated owner being created (telephone normalized)
829	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
830	     */
831	    private Integer possibleDuplicateOf(Owner owner) {
832	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
833	            return null;
834	        }
835	        String key = identityKey(owner);
836	        String lastNameSoundex = soundex.encode(owner.getLastName());
837	        return this.clinicService.findAllOwners().stream()
838	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
839	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
840	                && !key.equals(identityKey(existing)))
841	            .map(Owner::getId)
842	            .filter(java.util.Objects::nonNull)
843	            .findFirst()
844	            .orElse(null);
845	    }
846	
847	    /**
848	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
849	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
850	     * the owner's telephone reduced to its canonical E.164 form (see
851	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
852	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
853	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
854	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
855	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
856	     * value across owners.
857	     *
858	     * @param owner the owner to derive the identity key for
859	     * @return the owner's identity key, a 64-character lower-case hex string
860	     */
861	    private String identityKey(Owner owner) {
862	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
863	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
864	        String email = normalizedEmail == null ? "" : normalizedEmail;
865	        String lastNameSoundex = soundex.encode(owner.getLastName());
866	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
867	    }
868	
869	    /**
870	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
871	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
872	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
873	     * checks reduce both an existing owner and the owner being created to the same canonical key;
874	     * this returns the matched existing owner itself, so a caller can either reject the collision or
875	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
876	     * collision with only a deleted owner is not reported and the create is allowed.
877	     *
878	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
879	     * @param key the canonical key of the owner being created
880	     * @return the first existing owner sharing the key, or empty when none does
881	     */
882	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
883	        return this.clinicService.findAllOwners().stream()
884	            .filter(owner -> !owner.isDeleted())
885	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
886	            .findFirst();
887	    }
888	
889	    /**
890	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
891	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
892	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
893	     * being created to the same canonical key and reject a match.
894	     *
895	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
896	     * @param key the canonical key of the owner being created
897	     * @return {@code true} if some existing owner shares the key
898	     */
899	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
900	        return findExistingOwner(keyExtractor, key).isPresent();
901	    }
902	
903	    /**
904	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
905	     * count-based rules - the per-city capacity, the per-day create limit and the derived
906	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
907	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
908	     * place and each rule supplies just its own predicate.
909	     *
910	     * @param predicate the condition an owner must satisfy to be counted
911	     * @return the number of existing owners that satisfy the predicate
912	     */
913	    private long countOwners(Predicate<Owner> predicate) {
914	        return this.clinicService.findAllOwners().stream()
915	            .filter(predicate)
916	            .count();
917	    }
918	
919	    /**
920	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
921	     * shared {@code householdId}.
922	     */
923	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
924	
925	    /**
926	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
927	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
928	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
929	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
930	     *
931	     * @param value the raw field value, or {@code null}
932	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
933	     */
934	    private String canonicalizeHousehold(String value) {
935	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
936	    }
937	
938	    /**
939	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
940	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
941	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
942	     * for the last-name normalization), so every owner with the same last name and postcode -
943	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
944	     * a postcode have no household basis and are given no household id ({@code null}).
945	     *
946	     * @param owner the owner being created
947	     * @return the shared household identifier, or {@code null} when the owner has no postcode
948	     */
949	    /**
950	     * Counts the owners in the given owner's household: the existing owners that share its
951	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
952	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
953	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
954	     * household factor of the owner's membership points.
955	     *
956	     * @param owner the owner whose household size is being derived
957	     * @return the number of owners in the owner's household (at least {@code 1})
958	     */
959	    private int householdSize(Owner owner) {
960	        if (owner.getHouseholdId() == null) {
961	            return 1;
962	        }
963	        return householdMembers(owner).size();
964	    }
965	
966	    /**
967	     * The existing owners that make up the given owner's household: those sharing its
968	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
969	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
970	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
971	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
972	     * counts it among its household, while one taken before the save sees only the owners already
973	     * present. Holding the household lookup in one place lets every household-derived value read the
974	     * same set of members.
975	     *
976	     * @param owner the owner whose household members are wanted
977	     * @return the owners sharing the owner's household, or an empty list when it has no household
978	     */
979	    private List<Owner> householdMembers(Owner owner) {
980	        String household = owner.getHouseholdId();
981	        if (household == null) {
982	            return List.of();
983	        }
984	        return this.clinicService.findAllOwners().stream()
985	            .filter(existing -> household.equals(existing.getHouseholdId()))
986	            .toList();
987	    }
988	
989	    private String householdId(Owner owner) {
990	        String postcode = owner.getPostcode();
991	        if (postcode == null || postcode.isBlank()) {
992	            return null;
993	        }
994	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
995	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
996	    }
997	
998	    /**
999	     * Number of leading hex characters of the household hash retained as the shared
1000	     * {@code householdId}.
1001	     */
1002	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1003	}
